1: //! Repository-visible dependency target classification helpers.
2: //!
3: //! The classifier is intentionally small and deterministic: callers provide the
4: //! queued and in-flight sets from scheduler/analyzer state, plus archive evidence
5: //! collected from the workspace or base tree. No durable state outside the
6: //! repository participates in the decision.
7: 
8: use std::collections::HashSet;
9: use std::path::Path;
10: use tracing::warn;
11: 
12: /// Classification for a dependency target referenced by an active change.
13: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
14: pub(crate) enum DependencyTargetClass {
15:     Queued,
16:     InFlight,
17:     Archived,
18:     Missing,
19: }
20: 
21: impl DependencyTargetClass {
22:     pub(crate) fn as_str(self) -> &'static str {
23:         match self {
24:             Self::Queued => "queued",
25:             Self::InFlight => "in-flight",
26:             Self::Archived => "archived",
27:             Self::Missing => "missing",
28:         }
29:     }
30: }
31: 
32: /// Strip Conflux archive date prefixes such as `2026-04-29-change-id`.
33: pub(crate) fn strip_archive_date_prefix(name: &str) -> &str {
34:     if name.len() > 11 {
35:         let bytes = name.as_bytes();
36:         let has_date_prefix = bytes[4] == b'-'
37:             && bytes[7] == b'-'
38:             && bytes[10] == b'-'
39:             && bytes[..4].iter().all(u8::is_ascii_digit)
40:             && bytes[5..7].iter().all(u8::is_ascii_digit)
41:             && bytes[8..10].iter().all(u8::is_ascii_digit);
42:         if has_date_prefix {
43:             return &name[11..];
44:         }
45:     }
46:     name
47: }
